$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'PR1B v3 pre-pilot v6 requires an explicit absolute ProjectPath.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13RPR1BPrePilotV6|$ProjectPath");exit 0}
$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate13RPR1BOrderEffectPreparationV4.psm1') -Force
$plan=Read-Gate13RPR1BV3Json $PilotPlanPath;$provenance=Read-Gate13RPR1BV3Json $ProvenancePath;Assert-Gate13RPR1BV3PlanIdentity $plan
$root=[IO.Path]::GetFullPath((Join-Path $ProjectPath ([string]$plan.paths.verificationRootRelativePath).Replace('/','\')));$base=[IO.Path]::GetFullPath((Join-Path $ProjectPath 'Research\Verification\Gate12R_ProcessReuse_5pct'))
if(-not$root.StartsWith($base.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'PR1B v3 verification root is outside versioned Gate12R containment.'};if(Test-Path $root){throw "Create-new PR1B v3 verification root exists: $root"}
$pilotRoot=Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\');$formalRoot=Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')
if(Test-Path $pilotRoot){throw 'PR1B v3 pilot root must be absent during pre-pilot.'};if(Test-Path $formalRoot){throw 'Reserved formal root must be absent.'};if(@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-or(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))){throw 'Unity must be closed and unlocked before PR1B v3 pre-pilot.'}
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');if(-not(Test-Path $path)-or(Get-Gate13RPR1BV3LowerSha256 $path)-ne[string]$binding.sha256){throw "Pre-pilot provenance binding failed: $($binding.relativePath)"}}
New-Item -ItemType Directory -Path $root -Force|Out-Null;New-Item -ItemType Directory -Path (Join-Path $root 'Orchestration') -Force|Out-Null
$winps='C:\WINDOWS\System32\WindowsPowerShell\v1.0\powershell.exe';$native=@('C:\Users\bdscy\Documents\WindowsPowerShell\Modules','C:\Program Files\WindowsPowerShell\Modules','C:\WINDOWS\System32\WindowsPowerShell\v1.0\Modules')-join';'
function Invoke-Step([string]$Name,[string]$Script,[string[]]$Arguments){$stdout=Join-Path $root ('Orchestration\'+$Name+'.stdout.log');$stderr=Join-Path $root ('Orchestration\'+$Name+'.stderr.log');$old=$env:PSModulePath;try{$env:PSModulePath=$native;&$winps -NoProfile -ExecutionPolicy Bypass -File $Script @Arguments 1>$stdout 2>$stderr;$exit=[int]$LASTEXITCODE}finally{$env:PSModulePath=$old};if($exit-ne0){$detail='';if(Test-Path $stderr){$detail=(Get-Content -LiteralPath $stderr -Raw -ErrorAction SilentlyContinue)};throw "$Name failed: exit=$exit stderr=$stderr detail=$detail"}}
function Write-Checkpoint([string]$Status,[string]$Message){$value=[ordered]@{schemaVersion=3;checkpointKind='gate13r-pr1b-v3-pathsafe-prepilot-checkpoint-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');status=$Status;message=$Message;pilotPlanSha256=Get-Gate13RPR1BV3LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV3LowerSha256 $ProvenancePath;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BV3AtomicUtf8NoBomJson -Path (Join-Path $root 'checkpoint.json') -Value $value -Depth 15}
function Get-BoundedSharedReadSha256([string]$Path){$last=$null;for($i=1;$i-le30;$i++){try{$share=[IO.FileShare]::ReadWrite-bor[IO.FileShare]::Delete;$stream=[IO.File]::Open($Path,[IO.FileMode]::Open,[IO.FileAccess]::Read,$share);try{$sha=[Security.Cryptography.SHA256]::Create();try{return [pscustomobject]@{available=$true;sha256=([BitConverter]::ToString($sha.ComputeHash($stream))).Replace('-','').ToLowerInvariant();attempts=$i;error=$null}}finally{$sha.Dispose()}}finally{$stream.Dispose()}}catch{$last=$_.Exception.Message;Start-Sleep -Milliseconds 100}};return [pscustomobject]@{available=$false;sha256=$null;attempts=30;error=$last}}
function Write-Partial([string]$Status){$files=@(Get-ChildItem -LiteralPath $root -Recurse -File -Force|Where-Object{$_.Name-notlike'*.tmp-*' -and$_.Name-ne'partial-output-manifest.json'});$rows=@($files|ForEach-Object{$hash=Get-BoundedSharedReadSha256 $_.FullName;[pscustomobject][ordered]@{relativePath=Get-Gate13RPR1BV3ProjectRelativePath $ProjectPath $_.FullName;rawBytes=[long]$_.Length;sha256=$hash.sha256;hashAvailable=[bool]$hash.available;hashAttempts=[int]$hash.attempts;hashError=$hash.error}});Write-Gate13RPR1BV3AtomicUtf8NoBomJson -Path (Join-Path $root 'partial-output-manifest.json') -Value ([ordered]@{schemaVersion=3;manifestKind='gate13r-pr1b-v3-pathsafe-prepilot-partial-output-manifest-v1';status=$Status;savedAtUtc=[DateTime]::UtcNow.ToString('o');fileCount=$rows.Count;hashUnavailableCount=@($rows|Where-Object{-not$_.hashAvailable}).Count;files=$rows;formalCampaign=$false}) -Depth 40}
try{
 $receipt=[ordered]@{schemaVersion=3;receiptKind='gate13r-pr1b-v3-pathsafe-prepilot-execution-receipt-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');verificationRoot=$root;pilotPlanSha256=Get-Gate13RPR1BV3LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV3LowerSha256 $ProvenancePath;unitySha256=Get-Gate13RPR1BV3LowerSha256 $UnityPath;operationalRepair='winps51-same-directory-backup-leaf-atomic-replace-v1';nonFormal=$true;formalCampaign=$false;gate13rFormalAuthorized=$false};Write-Gate13RPR1BV3AtomicUtf8NoBomJson -Path (Join-Path $root 'execution-receipt.json') -Value $receipt -Depth 15;Write-Checkpoint 'started' $null
 Invoke-Step '01-static-unit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BStaticUnitV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath);Write-Checkpoint 'static-unit-passed' $null
 Invoke-Step '02-compile' (Join-Path $ProjectPath 'Research\Verification\Run-Gate12RCompileV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'compile-passed' $null
 Invoke-Step '03-pathsafe-atomic-self-test' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BPathSafeAtomicSelfTestV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'pathsafe-atomic-self-test-passed' $null
 Invoke-Step '04-memory-policy-self-test' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BMemoryPolicySelfTestV5.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-UnityPath',$UnityPath);Write-Checkpoint 'memory-policy-self-test-passed' $null
 $telemetryOutput=Join-Path $root 'TelemetryProbe\v3';Invoke-Step '05-telemetry' (Join-Path $ProjectPath 'Research\Run-Gate13RPR1BMemoryTelemetryProbeV4.ps1') @('-ProjectPath',$ProjectPath,'-OutputDirectory',$telemetryOutput,'-AllowedRoot',$root,'-UnityPath',$UnityPath);$telemetryResult=Join-Path $telemetryOutput 'telemetry-probe-result.json';Write-Checkpoint 'telemetry-passed' $null
 Invoke-Step '06-block-verification' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BBlockVerificationV5.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult,'-UnityPath',$UnityPath);Write-Checkpoint 'block-repeatability-cold-retained-passed' $null
 Invoke-Step '07-validation-only-audit' (Join-Path $ProjectPath 'Research\Verification\Run-Gate13RPR1BValidationOnlyPrePilotAuditV4.ps1') @('-ProjectPath',$ProjectPath,'-VerificationRoot',$root,'-PilotPlanPath',$PilotPlanPath,'-ProvenancePath',$ProvenancePath,'-TelemetryResultPath',$telemetryResult);$audit=Read-Gate13RPR1BV3Json (Join-Path $root 'ValidationOnlyPrePilotAudit.summary.json');if($audit.passed-ne$true-or$audit.pilotExecutionAuthorized-ne$true){throw 'Final PR1B v3 validation-only audit did not authorize pilot execution.'}
